// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Meter } from "@/registry/erbium/ui/meter";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import OverviewExample from "./variants/overview";



import RangeExample from "./variants/range";



const meta = {
  component: Meter,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Shows a scalar value within a known range, such as disk usage or a score. Built on Base UI's `Meter`, which exposes `role="meter"` with the value, min and max. For work moving toward completion use `Progress`.

**Import:** `@/registry/erbium/ui/meter`

```tsx
import { Meter, MeterLabel, MeterValue } from "@/registry/erbium/ui/meter";
```

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Meter](https://base-ui.com/react/components/meter)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Meter>;

export default { ...meta, title: "Components/Meter",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Meter> = {
  argTypes: {
    max: { control: "number" },
    min: { control: "number" },
    value: { control: { max: 100, min: 0, step: 1, type: "range" } },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Meter, MeterIndicator, MeterTrack } from "@/registry/erbium/ui/meter";
import type * as React from "react";

export const defaultProps = { max: 100, min: 0, value: 24 } satisfies React.ComponentProps<
  typeof Meter
>;

export default function MeterPlaygroundExample(
  args: React.ComponentProps<typeof Meter> = defaultProps,
) {
  return (
    <Meter {...args} className="w-72" aria-label="Storage used">
      <MeterTrack>
        <MeterIndicator />
      </MeterTrack>
    </Meter>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import {
  Meter,
  MeterIndicator,
