export const Range: Story = {
  parameters: {
    docs: {
      description: { story: "Set `min`, `max` and `format` to show the value in its own units." },
      source: { code: "import {
  Meter,
  MeterIndicator,
  MeterLabel,
  MeterTrack,
  MeterValue,
} from "@/registry/erbium/ui/meter";

export default function MeterRangeExample() {
  return (
    <Meter
      value={72}
      min={0}
      max={100}
      format={{ style: "unit", unit: "percent" }}
      className="w-72"
    >
      <MeterLabel>Battery</MeterLabel>
      <MeterValue />
      <MeterTrack>
        <MeterIndicator />
      </MeterTrack>
    </Meter>
  );
}
" },
    },
  },
  render: RangeExample,
